# Since Alpine 3.18 one linux-rpi kernel covers every supported Pi model of the architecture
# (armhf: Pi Zero/1/2/3, armv7: Pi 2/3/4, aarch64: Pi 3/4/5) and ships the dtbs and overlays in /boot.
setup-kernel(){
  chmnt apk add -q linux-rpi raspberrypi-bootloader
}

setup-boot(){
  chmnt apk add -q dosfstools e2fsprogs

  local root
  root=$(blkid -s UUID -o value "$ROOT_DEV")

  # Matches the Alpine RPi release: config.txt is regenerated by Alpine tooling, users edit usercfg.txt.
  {
    echo '# https://www.raspberrypi.com/documentation/computers/config_txt.html'
    echo 'disable_splash=1'
    echo 'boot_delay=0'
    [ "$ARCH" = aarch64 ] && echo 'arm_64bit=1'
    echo 'kernel=vmlinuz-rpi'
    echo 'initramfs initramfs-rpi'
    echo 'include usercfg.txt'
  } > "$MNT/boot/config.txt"
  [ -f "$MNT/boot/usercfg.txt" ] || echo '# Local overrides, e.g. enable_uart=1 or dtoverlay=...' > "$MNT/boot/usercfg.txt"

  # UUID lets the same image boot from SD card or USB disk.
  echo "modules=sd-mod,usb-storage,ext4 root=UUID=${root} rootfstype=ext4 fsck.repair=yes rootwait console=serial0,115200 console=tty1" > "$MNT/boot/cmdline.txt"

  cat > "$MNT/etc/fstab" <<FSTAB
UUID=${root}  /      ext4  defaults,noatime  0 1
LABEL=RPI-BOOT /boot  vfat  defaults          0 2
FSTAB
}
